package com.oms.order.service;
import com.ruoyi.common.core.domain.R;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.util.ReflectionTestUtils;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static com.oms.order.service.OrderValues.*;

class OrderAutoAllocationServiceTest {
    OrderAllocationServiceTest fixture;OrderAutoAllocationService service;JdbcTemplate db;OrderRepository repository;
    @BeforeAll static void setup(){OrderAllocationServiceTest.setup();}
    @BeforeEach void seed(){
        db=OrderAllocationServiceTest.db;db.update("DELETE FROM oms_order_auto_allocation");fixture=new OrderAllocationServiceTest();fixture.seed();
        repository=new OrderRepository();ReflectionTestUtils.setField(repository,"jdbc",db);
        service=new OrderAutoAllocationService();ReflectionTestUtils.setField(service,"repository",repository);ReflectionTestUtils.setField(service,"allocation",fixture.service);ReflectionTestUtils.setField(service,"inventory",fixture.warehouse);
        when(fixture.warehouse.stockSignals(anyString(),anyString())).thenReturn(R.ok(Collections.emptyList()));when(fixture.warehouse.ackStockSignal(anyString(),anyMap(),anyString())).thenReturn(R.ok(Collections.emptyMap()));
        when(fixture.warehouse.preview(anyString(),anyMap(),anyString())).thenReturn(R.ok(fixture.row("can_allocate",true,"plan_fingerprint","current")));
        when(fixture.warehouse.allocate(anyString(),anyMap(),anyString())).thenReturn(R.ok(fixture.receipts(10)));
    }
    void config(boolean replenish){Map<String,Object> p=fixture.config();p.put("execution_mode","AUTO");p.put("auto_replenish",replenish?1:0);db.update("UPDATE oms_order_allocation_config SET policy_json=?",encode(p));}
    void enqueue(){assertTrue(OrderAutoAllocationService.enqueue(db,"VERIFY",fixture.id,"test"));}
    String state(){return db.queryForObject("SELECT state FROM oms_order_auto_allocation WHERE company_code='VERIFY' AND order_id=?",String.class,fixture.id);}
    void due(){db.update("UPDATE oms_order_auto_allocation SET next_attempt=DATE_SUB(NOW(),INTERVAL 1 SECOND),lease_until=NULL");}
    @Test void manualModeDoesNotCreateAutomaticWork(){assertFalse(OrderAutoAllocationService.enqueue(db,"VERIFY",fixture.id,"manual"));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM oms_order_auto_allocation",Integer.class));verifyNoInteractions(fixture.warehouse);}
    @Test void duplicateTriggersAndRepeatedScansCreateOnlyOneOccupation(){config(true);enqueue();enqueue();assertEquals(1,service.due("VERIFY").size());service.process("VERIFY",fixture.id);assertEquals("DONE",state());service.process("VERIFY",fixture.id);verify(fixture.warehouse,times(1)).allocate(anyString(),anyMap(),anyString());assertEquals(10,db.queryForObject("SELECT allocation_quantity FROM oms_order",Integer.class));}
    @Test void heldAndBlockedOrdersNeverCallInventory(){config(true);enqueue();db.update("UPDATE oms_order SET manual_hold=1");service.process("VERIFY",fixture.id);assertEquals("WAIT_CONDITION",state());verify(fixture.warehouse,never()).allocate(anyString(),anyMap(),anyString());due();db.update("UPDATE oms_order SET manual_hold=0");db.update("UPDATE oms_platform_order SET fulfillment_block_reason='refund'");service.process("VERIFY",fixture.id);assertEquals("WAIT_CONDITION",state());verify(fixture.warehouse,never()).preview(anyString(),anyMap(),anyString());}
    @Test void insufficientLogicalReservationWaitsWithoutPreview(){config(true);enqueue();db.update("UPDATE oms_order_line SET reserved_quantity=0");service.process("VERIFY",fixture.id);assertEquals("WAIT_STOCK",state());verify(fixture.warehouse,never()).preview(anyString(),anyMap(),anyString());}
    @Test void previewShortageSleepsRatherThanSystemFailure(){config(true);enqueue();when(fixture.warehouse.preview(anyString(),anyMap(),anyString())).thenReturn(R.ok(fixture.row("can_allocate",false,"retry_kind","STOCK","message","仓库库存不足")));service.process("VERIFY",fixture.id);assertEquals("WAIT_STOCK",state());assertEquals(0,db.queryForObject("SELECT failures FROM oms_order_auto_allocation",Integer.class));verify(fixture.warehouse,never()).allocate(anyString(),anyMap(),anyString());}
    @Test void invalidMappingRequiresHumanAction(){config(true);enqueue();when(fixture.catalog.warehouses("VERIFY")).thenReturn(Collections.emptyList());service.process("VERIFY",fixture.id);assertEquals("NEEDS_ACTION",state());assertNull(db.queryForObject("SELECT next_attempt FROM oms_order_auto_allocation",java.sql.Timestamp.class));}
    @Test void partialThenReplenishedUsesSnapshotAndAddsOnlyRemainingReceipts(){config(true);enqueue();when(fixture.warehouse.allocate(anyString(),anyMap(),anyString())).thenReturn(R.ok(fixture.receipts(5)));service.process("VERIFY",fixture.id);assertEquals("WAIT_STOCK",state());Map<String,Object> p=fixture.config();p.put("execution_mode","AUTO");p.put("auto_replenish",1);p.put("allow_partial",0);db.update("UPDATE oms_order_allocation_config SET policy_json=?",encode(p));due();when(fixture.warehouse.allocate(anyString(),anyMap(),anyString())).thenAnswer(call->{assertEquals(1,number(call.getArgument(1),"allow_partial"));return R.ok(fixture.receipts(10));});service.process("VERIFY",fixture.id);assertEquals("DONE",state());assertEquals(10,db.queryForObject("SELECT SUM(quantity) FROM oms_order_shipment",Integer.class));assertEquals(2,db.queryForObject("SELECT COUNT(*) FROM oms_order_shipment",Integer.class));}
    @Test void partialWorkDoesNotContinueWhenAutomaticReplenishIsOff(){config(false);enqueue();when(fixture.warehouse.allocate(anyString(),anyMap(),anyString())).thenReturn(R.ok(fixture.receipts(5)));service.process("VERIFY",fixture.id);assertEquals("PARTIAL_PAUSED",state());assertFalse(OrderAutoAllocationService.enqueue(db,"VERIFY",fixture.id,"restock"));due();service.process("VERIFY",fixture.id);verify(fixture.warehouse,times(1)).allocate(anyString(),anyMap(),anyString());}
    @Test void taskPauseSurvivesNewTriggersAndCanResume(){config(true);enqueue();service.action("VERIFY",fixture.id,"pause",0,"admin");enqueue();service.process("VERIFY",fixture.id);verify(fixture.warehouse,never()).allocate(anyString(),anyMap(),anyString());assertEquals("PAUSED",service.report("VERIFY",fixture.id).get("state"));service.action("VERIFY",fixture.id,"resume",1,"admin");service.process("VERIFY",fixture.id);assertEquals("DONE",state());}
    @Test void serviceFaultsBackOffAndStopAfterFiveAttempts(){config(true);enqueue();when(fixture.warehouse.preview(anyString(),anyMap(),anyString())).thenThrow(new IllegalStateException("unavailable"));for(int i=0;i<5;i++){due();service.process("VERIFY",fixture.id);}assertEquals("NEEDS_ACTION",state());assertEquals(5,db.queryForObject("SELECT failures FROM oms_order_auto_allocation",Integer.class));assertTrue(service.due("VERIFY").isEmpty());}
    @Test void uncertainRemoteCommitIsRecoveredWithoutAnotherAllocationCall(){config(true);enqueue();when(fixture.warehouse.allocate(anyString(),anyMap(),anyString())).thenThrow(new IllegalStateException("timeout"));service.process("VERIFY",fixture.id);assertEquals("UNCERTAIN",state());when(fixture.warehouse.receipts(anyString(),anyLong(),anyString(),anyString())).thenReturn(R.ok(fixture.receipts(10)));due();service.process("VERIFY",fixture.id);assertEquals("DONE",state());verify(fixture.warehouse,times(1)).allocate(anyString(),anyMap(),anyString());assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM oms_order_shipment",Integer.class));}
    @Test void expiredLeaseCanBeRecoveredAndOtherCompanyCannotClaimIt(){config(true);enqueue();db.update("UPDATE oms_order_auto_allocation SET state='PROCESSING',lease_token='dead',lease_until=DATE_SUB(NOW(),INTERVAL 1 SECOND)");service.process("OTHER",fixture.id);verify(fixture.warehouse,never()).allocate(anyString(),anyMap(),anyString());service.process("VERIFY",fixture.id);assertEquals("DONE",state());}
    @Test void stockSignalOnlyWakesMatchingAllowedVirtualWarehouse(){config(true);enqueue();db.update("UPDATE oms_order_auto_allocation SET state='WAIT_STOCK',next_attempt=DATE_ADD(NOW(),INTERVAL 300 SECOND)");when(fixture.warehouse.stockSignals(anyString(),anyString())).thenReturn(R.ok(Arrays.asList(fixture.row("sku_sn","A","store_code","V2","revision",1))));service.wakeStock("VERIFY");assertEquals("WAIT_STOCK",state());when(fixture.warehouse.stockSignals(anyString(),anyString())).thenReturn(R.ok(Arrays.asList(fixture.row("sku_sn","A","store_code","V1","revision",2))));service.wakeStock("VERIFY");assertEquals("PENDING",state());assertEquals(1,service.due("VERIFY").size());}
    @Test void concurrentWorkersShareOneDurableClaim() throws Exception {config(true);enqueue();CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);when(fixture.warehouse.preview(anyString(),anyMap(),anyString())).thenAnswer(call->{entered.countDown();assertTrue(release.await(10,TimeUnit.SECONDS));return R.ok(fixture.row("can_allocate",true,"plan_fingerprint","current"));});ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<?> first=pool.submit(()->service.process("VERIFY",fixture.id));assertTrue(entered.await(10,TimeUnit.SECONDS));Future<?> second=pool.submit(()->service.process("VERIFY",fixture.id));second.get(10,TimeUnit.SECONDS);release.countDown();first.get(10,TimeUnit.SECONDS);}finally{release.countDown();pool.shutdownNow();}verify(fixture.warehouse,times(1)).allocate(anyString(),anyMap(),anyString());assertEquals("DONE",state());}
    @Test void modeChangedDuringPreviewPreventsCommit(){config(true);enqueue();when(fixture.warehouse.preview(anyString(),anyMap(),anyString())).thenAnswer(call->{Map<String,Object> p=fixture.config();p.put("execution_mode","MANUAL");db.update("UPDATE oms_order_allocation_config SET policy_json=?",encode(p));return R.ok(fixture.row("can_allocate",true,"plan_fingerprint","old"));});service.process("VERIFY",fixture.id);assertEquals("NEEDS_ACTION",state());verify(fixture.warehouse,never()).allocate(anyString(),anyMap(),anyString());}
}
